//! Embedded data of a v3.4.2 database freshly created with upstream `manage.py migrate`.
//!
//! - Schema (pre/post-data, columns, migration lists): reused from pl-dbmigrate
//!   (`crates/pl-dbmigrate/schema/`, generated by `tests/dbmigrate/gen_schema.sh`).
//! - ContentTypes, permissions, `django_migrations` in application order, exporter descriptor:
//!   `crates/pl-cli/baseline/`, generated by `tests/parity/pl-cli/gen_baseline.sh` (upstream
//!   `migrate` on an empty DB; `gen_descriptor.py` reads Django `_meta`).

pub const SCHEMA_PRE: &str = include_str!("../../pl-dbmigrate/schema/v3.4.2-postgres-pre.sql");
pub const SCHEMA_POST: &str = include_str!("../../pl-dbmigrate/schema/v3.4.2-postgres-post.sql");
pub const COLUMNS_TSV: &str = include_str!("../../pl-dbmigrate/schema/v3.4.2-columns.tsv");
pub const MIGRATIONS_TSV: &str = include_str!("../../pl-dbmigrate/schema/v3.4.2-migrations.tsv");
pub const REPLACED_TSV: &str = include_str!("../../pl-dbmigrate/schema/v3.4.2-replaced.tsv");
pub const HISTORICAL_TSV: &str = include_str!("../../pl-dbmigrate/schema/v3.4.2-historical.tsv");
/// Catch-up v3.0.0 … v3.4.1 → v3.4.2 (same file as pl-dbmigrate `catchup.rs`).
pub const CATCHUP_SQL: &str = include_str!("../../pl-dbmigrate/schema/catchup-v3.0.0-v3.4.2.sql");

pub const CONTENT_TYPES_TSV: &str = include_str!("../baseline/v3.4.2-content-types.tsv");
pub const PERMISSIONS_TSV: &str = include_str!("../baseline/v3.4.2-permissions.tsv");
pub const MIGRATIONS_APPLIED_TSV: &str = include_str!("../baseline/v3.4.2-migrations-applied.tsv");
pub const EXPORT_DESCRIPTOR_JSON: &str = include_str!("../baseline/export-descriptor.json");

/// Django apps of v3.4.2 (`INSTALLED_APPS` with migrations).
pub fn installed_apps() -> std::collections::BTreeSet<String> {
    rows(MIGRATIONS_TSV).into_iter().filter_map(|r| r.first().map(|s| s.to_string())).collect()
}

/// TSV without comment lines (`#`) and blank lines.
pub fn rows(tsv: &str) -> Vec<Vec<&str>> {
    tsv.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()).map(|l| l.split('\t').collect()).collect()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ContentType {
    pub id: i32,
    pub app_label: String,
    pub model: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Permission {
    pub id: i32,
    pub content_type_id: i32,
    pub codename: String,
    pub name: String,
}

pub fn content_types() -> Vec<ContentType> {
    rows(CONTENT_TYPES_TSV)
        .into_iter()
        .filter_map(|r| {
            Some(ContentType { id: r.first()?.parse().ok()?, app_label: (*r.get(1)?).to_string(), model: (*r.get(2)?).to_string() })
        })
        .collect()
}

pub fn permissions() -> Vec<Permission> {
    rows(PERMISSIONS_TSV)
        .into_iter()
        .filter_map(|r| {
            Some(Permission {
                id: r.first()?.parse().ok()?,
                content_type_id: r.get(1)?.parse().ok()?,
                codename: (*r.get(2)?).to_string(),
                name: (*r.get(3)?).to_string(),
            })
        })
        .collect()
}

/// `(app, name)` in application order.
pub fn migrations_applied() -> Vec<(String, String)> {
    rows(MIGRATIONS_APPLIED_TSV).into_iter().filter_map(|r| Some(((*r.first()?).to_string(), (*r.get(1)?).to_string()))).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn baseline_is_consistent() {
        let cts = content_types();
        let perms = permissions();
        let migs = migrations_applied();
        assert_eq!(cts.len(), 42);
        assert_eq!(perms.len(), 170);
        assert_eq!(migs.len(), 247);
        // every permission points to a ContentType
        for p in &perms {
            assert!(cts.iter().any(|c| c.id == p.content_type_id), "{p:?}");
        }
        // application order = same set as pl-dbmigrate
        let mut a: Vec<(String, String)> = migs.clone();
        a.sort();
        let mut b: Vec<(String, String)> = rows(MIGRATIONS_TSV).into_iter().map(|r| (r[0].to_string(), r[1].to_string())).collect();
        b.sort();
        assert_eq!(a, b);
        assert!(SCHEMA_PRE.contains("CREATE TABLE public.documents_document"));
        assert!(serde_json::from_str::<serde_json::Value>(EXPORT_DESCRIPTOR_JSON).is_ok());
    }
}
